pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 firstValue, uint256 secondValue, uint256 unlockTime) public {
        // Restrict values to avoid overflow revert on addition (firstValue + secondValue <= type(uint256).max)
