pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 prevValue, uint256 putValue, uint256 unlockTime) public {
        // 1. Bound to avoid overflow and keep amounts reasonable
        prevValue = bound(prevValue, 0, type(uint128).max);
        putValue = bound(putValue, 0, type(uint128).max);
        unlockTime = bound(unlockTime, block.timestamp + 1, type(uint64).max);

        // Use a fresh address as the actor
        address actor = address(uint160(uint256(keccak256(abi.encode(prevValue, putValue, unlockTime)))));

        // First Put to establish a non-zero balance (prevValue)
        if (prevValue > 0) {
            vm.deal(actor, prevValue);
            vm.prank(actor);
            c.Put{value: prevValue}(unlockTime);
        }

        // Record the balance before the second Put
        uint256 balanceBefore = c.Acc(actor).balance;

        // Second Put with putValue
        vm.deal(actor, putValue);
        vm.prank(actor);
        c.Put{value: putValue}(unlockTime);

        // Record the balance after the second Put
        uint256 balanceAfter = c.Acc(actor).balance;

        // The invariant: new balance must equal old balance + sent value
        assertEq(balanceAfter, balanceBefore + putValue);
    }
}

