pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 firstValue, uint256 secondValue, address caller) public {
        // Restrict values so that the first call does not cause an overflow in the require check and
        // both calls are non-zero, and ensure the second value is strictly less than the first.
        vm.assume(firstValue > 0 && secondValue > 0);
        vm.assume(firstValue < type(uint256).max);
        vm.assume(secondValue < firstValue);
        // Avoid the precompile / zero address / this test contract itself so setup is clean
        vm.assume(caller != address(0) && caller != address(this) && caller != address(c));

        // Fund the caller for both transactions
        vm.deal(caller, firstValue + secondValue);

        // First Put call with firstValue
        vm.prank(caller);
        c.Put{value: firstValue}(0);

        uint256 balanceAfterFirst = c.Acc(caller);

        // Second Put call with secondValue (smaller than firstValue)
        vm.prank(caller);
        c.Put{value: secondValue}(0);

        uint256 balanceAfterSecond = c.Acc(caller);

        // In the correct contract, the balance must increase after the second deposit.
        assertTrue(balanceAfterSecond > balanceAfterFirst);
    }
}

