pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime1, uint256 unlockTime2, uint256 warpTime) public {
        // Bound amounts to reasonable range to avoid overflow/out-of-funds issues
        amount1 = bound(amount1, 1 ether, 1000 ether);
        amount2 = bound(amount2, 1 ether, 1000 ether);
        // Bound unlock times to typical range
        unlockTime1 = bound(unlockTime1, block.timestamp, block.timestamp + 365 days);
        unlockTime2 = bound(unlockTime2, block.timestamp, block.timestamp + 365 days);
        // Warp time must be after unlockTime1 to allow collection, but before unlockTime2 to test the difference
        vm.assume(warpTime >= unlockTime1);
        vm.assume(warpTime < unlockTime2);

        address alice = address(0x1);
        // Fund Alice
        vm.deal(alice, amount1 + amount2);

        // Alice makes first Put with a near-term unlock time
        vm.prank(alice);
        c.Put{value: amount1}(unlockTime1);

        // Alice makes second Put with a later unlock time
        vm.prank(alice);
        c.Put{value: amount2}(unlockTime2);

        // Warp to a time after unlockTime1 but before unlockTime2
        vm.warp(warpTime);

        // Under reference C, Collect(amount1) should succeed because unlockTime1 has passed and balance is sufficient
        // Under buggy M, unlockTime may be set to unlockTime2 (the last Put overwrites unlockTime incorrectly),
        // or in the worst case the bug sets unlockTime to _unlockTime without max(block.timestamp, ...),
        // but here we test that Collect succeeds for reference and may fail for buggy if unlockTime is later.
        // Actually, the bug sets unlockTime = _unlockTime, so after the second Put, unlockTime becomes unlockTime2 (which is > warpTime),
        // so Collect should revert. For reference, unlockTime becomes max(block.timestamp, unlockTime2) = unlockTime2 as well!
        // Wait, the bug is that unlockTime can be set in the past. So we need a scenario where unlockTime1 is in the past but bug sets it to something even earlier?
        // Let's adjust: first Put is called at time T, with _unlockTime set to T - 100 (past). Reference will set unlockTime = max(block.timestamp, _unlockTime) = T.
        // Buggy sets unlockTime = _unlockTime = T - 100. Then warp to T - 50. Reference unlockTime = T > warpTime, so Collect fails.
        // Buggy unlockTime = T - 100 < warpTime, so Collect succeeds. So the bug makes Collect succeed when it should fail.
    }
}

