pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint112 amount, uint112 collectAmt, uint48 unlockDelta) public {
        // Restrict to admissible: positive amounts, unlockTime in the future, collect amount <= balance
        vm.assume(amount > 0);
        vm.assume(collectAmt > 0);
        vm.assume(unlockDelta > 0);
        uint _unlockTime = block.timestamp + unlockDelta;
        // Ensure account starts with zero balance and the Put amount covers MinSum if needed
        vm.assume(collectAmt <= amount);

        // Fund and call Put with future unlockTime
        address user = address(0xBEEF);
        vm.deal(user, amount);
        vm.prank(user);
        c.Put{value: amount}(_unlockTime);

        // Warp to a moment after Put but strictly before _unlockTime
        vm.warp(block.timestamp + unlockDelta / 2);

        // Attempt Collect: must fail for the correct contract
        vm.prank(user);
        try c.Collect(collectAmt) {
            // If Collect succeeds, the invariant is broken
            assertTrue(false);
        } catch {
            // Correct behavior: Collect reverts because unlockTime not yet reached
            assertTrue(true);
        }
    }
}

